import{_ as a,o as e,c as n,a2 as l}from"./chunks/framework.BUwdTBzS.js";const u=JSON.parse('{"title":"对话窗口 Token 管理","description":"","frontmatter":{"title":"对话窗口 Token 管理"},"headers":[],"relativePath":"dev-flow/references/token-management.md","filePath":"dev-flow/references/token-management.md","lastUpdated":null}'),s={name:"dev-flow/references/token-management.md"};function o(i,t,r,d,p,c){return e(),n("div",null,[...t[0]||(t[0]=[l(`<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/token-management.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="对话窗口-token-管理" tabindex="-1">对话窗口 Token 管理 <a class="header-anchor" href="#对话窗口-token-管理" aria-label="Permalink to &quot;对话窗口 Token 管理&quot;">​</a></h1><blockquote><p>管理<strong>当前对话窗口</strong>的信息密度，避免上下文膨胀导致 AI 遗忘早期约束。与「工作上下文持久化」互补——后者负责跨对话的磁盘文件，本章负责单次对话内的信息精简。 与「AI 行为规范 → 对话质量守卫」互补——后者是全局兜底（alwaysApply），本章是 dev-flow 内的精细管理（按需加载）。</p></blockquote><h2 id="与全局规则的关系" tabindex="-1">与全局规则的关系 <a class="header-anchor" href="#与全局规则的关系" aria-label="Permalink to &quot;与全局规则的关系&quot;">​</a></h2><p>「AI 行为规范 → 对话质量守卫」提供全局预警（黄色 &gt;15 轮 / 红色 &gt;25 轮）。 dev-flow 执行期间，本文件提供<strong>更精细的管理策略</strong>，两者叠加生效：</p><ul><li>全局规则负责「感知 + 预警 + 提醒用户」</li><li>本文件负责「压缩 + 精简 + 步骤级上下文卸载」</li></ul><h2 id="对话过长时的处理策略" tabindex="-1">对话过长时的处理策略 <a class="header-anchor" href="#对话过长时的处理策略" aria-label="Permalink to &quot;对话过长时的处理策略&quot;">​</a></h2><p>当前对话窗口约 200k Token。AI 无法精确感知用量，但可通过以下信号判断对话进入不同阶段：</p><table tabindex="0"><thead><tr><th>感知信号</th><th>阶段</th><th>动作</th></tr></thead><tbody><tr><td>对话轮数 &gt;15，或累计读取文件 &gt;10，或累计工具调用 &gt;40</td><td>中期</td><td>主动压缩：将已完成步骤精简为结论，移除过程细节</td></tr><tr><td>对话轮数 &gt;25，或累计读取文件 &gt;20，或检测到行为异常信号</td><td>后期</td><td>强制精简 + 建议开新对话（确保工作上下文已更新）</td></tr><tr><td>开始出现&quot;遗忘&quot;早期约束（如重复问已确认的事项）</td><td>随时</td><td>重读工作上下文文件，恢复关键约束</td></tr><tr><td>单次需求跨越 ≥3 个完整步骤且对话 &gt;20 轮</td><td>后期</td><td>在当前步骤完成后建议开新对话</td></tr></tbody></table><h3 id="步骤切换时的上下文卸载-dev-flow-专用" tabindex="-1">步骤切换时的上下文卸载（dev-flow 专用） <a class="header-anchor" href="#步骤切换时的上下文卸载-dev-flow-专用" aria-label="Permalink to &quot;步骤切换时的上下文卸载（dev-flow 专用）&quot;">​</a></h3><p>每完成一个步骤，执行以下卸载操作：</p><ol><li>将该步骤的过程细节（搜索结果、文件内容、中间分析）从心智模型中移除</li><li>仅保留该步骤的结论（写入工作上下文的内容）</li><li>如果下一步骤需要前序信息，从工作上下文文件重新读取（而非依赖对话记忆）</li></ol><h3 id="行为异常信号-质量衰减的直接证据" tabindex="-1">行为异常信号（质量衰减的直接证据） <a class="header-anchor" href="#行为异常信号-质量衰减的直接证据" aria-label="Permalink to &quot;行为异常信号（质量衰减的直接证据）&quot;">​</a></h3><blockquote><p>与「AI 行为规范 → 对话质量守卫」共享同一套信号定义，在 dev-flow 中额外关注步骤相关信号。</p></blockquote><ul><li><strong>重复提问</strong>：对用户已明确回答过的问题再次询问</li><li><strong>遗忘约束</strong>：违反了对话早期用户明确的约束或决策</li><li><strong>路径混淆</strong>：对已操作过的文件路径产生不确定</li><li><strong>方案矛盾</strong>：提出与之前已确认方案矛盾的建议</li><li><strong>工具调用失败率上升</strong>：连续 3 次工具调用参数错误</li><li><strong>步骤回退混乱</strong>（dev-flow 专用）：混淆当前步骤与已完成步骤的状态</li></ul><h2 id="信息精简规则" tabindex="-1">信息精简规则 <a class="header-anchor" href="#信息精简规则" aria-label="Permalink to &quot;信息精简规则&quot;">​</a></h2><p>每次工具调用后，主动评估输出体量并精简：</p><ul><li>工具调用结果体量明显过大 → 摘要为精要（保留关键结论、路径、行号）</li><li>代码搜索结果超过 15 个匹配 → 只保留前 8 个最相关</li><li>文件读取超过 800 行 → 提取关键区域 + 结构概要</li><li>已完成步骤的详细输出 → 仅保留结论，移除过程细节</li></ul><h2 id="结构化摘要模板" tabindex="-1">结构化摘要模板 <a class="header-anchor" href="#结构化摘要模板" aria-label="Permalink to &quot;结构化摘要模板&quot;">​</a></h2><p>对话中断需要恢复上下文、或对话过长需要压缩时，使用以下 7 段式结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. 用户意图：{一句话概括}</span></span>
<span class="line"><span>2. 技术决策：{已确认的关键技术选择}</span></span>
<span class="line"><span>3. 已修改文件：{文件列表 + 操作类型}</span></span>
<span class="line"><span>4. 问题与方案：{遇到的问题及解决方案}</span></span>
<span class="line"><span>5. 待处理任务：{剩余工作项}</span></span>
<span class="line"><span>6. 当前状态：{正在执行的步骤}</span></span>
<span class="line"><span>7. 用户约束：{用户明确的限制/要求}</span></span></code></pre></div>`,21)])])}const g=a(s,[["render",o]]);export{u as __pageData,g as default};
